//! 🧪️ Direct native fields preserve source and partial destination ownership across every original cancellation turn.
use super::*;
static JOB_DROPS:AtomicUsize=AtomicUsize::new(0);
#[repr(transparent)]
struct NativeJob(Vec<u8>);
impl Drop for NativeJob{fn drop(&mut self){assert_eq!(self.0.capacity(),0);JOB_DROPS.fetch_add(1,Ordering::Relaxed);}}
impl InteractiveJob for NativeJob{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,ValueError>{JobOutcomeBorrow::admit_yield(cx)}
 fn borrow_outcome<'a>(&'a self,d:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{d.yielded()}
 fn begin_close(&mut self){}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.0.capacity())}
 fn close_step(&mut self,grant:RetainedCloneGrant)->InteractiveJobCloseStep{if self.0.capacity()==0{return InteractiveJobCloseStep::Complete{progress:Default::default()}}let released_bytes=self.0.capacity();if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_release_bytes<released_bytes{return InteractiveJobCloseStep::Pending{progress:Default::default()}}drop(std::mem::take(&mut self.0));InteractiveJobCloseStep::Pending{progress:RetainedCloneProgress{copied_items:1,released_bytes,..Default::default()}}}
 fn terminal_is_empty(&self)->bool{self.0.capacity()==0}
}
struct NativeInitializer{source:Option<Vec<u8>>,target_present:bool,phase:usize,written:usize,target_pointer:usize}
unsafe impl WorkerJobInitializer<NativeJob> for NativeInitializer{
 fn initialization_demand(&self,maximum_copy_bytes:usize)->Result<RetirementDemand,ValueError>{Ok(match self.phase{0=>RetirementDemand{capacity_bytes:8192,depth:1,..Default::default()},1=>RetirementDemand{copy_bytes:(8192-self.written).min(maximum_copy_bytes.max(1)),depth:1,..Default::default()},2=>RetirementDemand{release_bytes:self.source.as_ref().unwrap().capacity(),depth:1,..Default::default()},_=>RetirementDemand{depth:1,..Default::default()}})}
 unsafe fn initialize_step(&mut self,target:*mut MaybeUninit<NativeJob>,grant:RetainedCloneGrant)->Result<WorkerJobInitializationStep,ValueError>{let mut progress=RetainedCloneProgress{copied_items:1,..Default::default()};match self.phase{0=>{unsafe{target.cast::<Vec<u8>>().write(Vec::new());}self.target_present=true;let destination=unsafe{&mut*target.cast::<Vec<u8>>()};destination.try_reserve_exact(8192).unwrap();progress.retained_capacity_bytes=destination.capacity();self.target_pointer=destination.as_ptr()as usize;self.phase=1;},1=>{let bytes=(8192-self.written).min(grant.maximum_copy_bytes);let destination=unsafe{&mut*target.cast::<Vec<u8>>()};destination.extend_from_slice(&self.source.as_ref().unwrap()[self.written..self.written+bytes]);self.written+=bytes;progress.copied_bytes=bytes;if self.written==8192{self.phase=2;}},2=>{progress.released_bytes=self.source.as_ref().unwrap().capacity();drop(self.source.take());self.phase=3;},_=>{self.target_present=false;self.phase=4;return Ok(WorkerJobInitializationStep{progress,complete:true});}}Ok(WorkerJobInitializationStep{progress,complete:false})}
 fn initialization_input_is_empty(&self)->bool{self.source.is_none()}
 fn partial_retirement_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{release_bytes:if self.target_present{8192}else{self.source.as_ref().map_or(0,Vec::capacity)},depth:1,..Default::default()})}
 unsafe fn close_partial_step(&mut self,target:*mut MaybeUninit<NativeJob>,_:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let released_bytes;if self.target_present{let original=unsafe{target.cast::<Vec<u8>>().read()};released_bytes=original.capacity();drop(original);self.target_present=false;}else{released_bytes=self.source.as_ref().map_or(0,Vec::capacity);drop(self.source.take());}Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes,..Default::default()}))}
 fn partial_terminal_is_empty(&self)->bool{!self.target_present&&self.source.is_none()}
}
fn now()->Option<u64>{Some(1)}
fn observed<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(value,(heap.requested_bytes,heap.released_bytes))}
fn turn<T>(grant:RetainedCloneGrant,f:impl FnOnce(&mut WorkerJobAdmissionContext<'_>)->T)->(T,RetainedCloneProgress){let mut receipt=Default::default();let mut control=WorkerJobAdmissionContext::new(OperationId(99930),Generation(7),StepBudget::new(1,2,grant),now,&mut receipt).unwrap();let output=f(&mut control);drop(control);assert!(receipt.fits(grant));(output,receipt)}
#[test]
fn original_native_preparation_writes_final_fields_and_preserves_every_paid_cancellation_frontier(){
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let metadata=RetainedCloneGrant{maximum_copy_bytes:0,..grant};
 for cut in[0,1,2,3,4,5,6,7,8,usize::MAX]{let before_drops=JOB_DROPS.load(Ordering::Relaxed);let mut source=Vec::new();let((),heap)=observed(||source.try_reserve_exact(8192).unwrap());let mut born=heap.0;assert_eq!(heap,(8192,0));for _ in 0..2{let((),heap)=observed(||source.extend_from_slice(&[71;4096]));assert_eq!(heap,(0,0));}let source_pointer=source.as_ptr();let mut initializer=NativeInitializer{source:Some(source),target_present:false,phase:0,written:0,target_pointer:0};let((cancel,birth),heap)=observed(||CancelToken::admit_root(metadata).unwrap().unwrap());assert_eq!((birth.retained_capacity_bytes,birth.released_bytes),heap);born+=heap.0;let mut params=Some(BatchJobParams{operation:OperationId(99930),generation:Generation(7),cancel,config:BatchDriveConfig{retained:grant,site:"test.original-native-preparation",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:1},now_us:now});
  let((owner,receipt),heap)=observed(||turn(grant,|cx|WorkerJobSessionPreparation::try_begin(&mut initializer,&mut params,cx).unwrap().unwrap()));let(mut owner,step)=owner;assert_eq!(step,receipt);assert_eq!(receipt.copied_bytes,26);assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),heap);born+=heap.0;let mut released=0;let mut copied=receipt.copied_bytes;let mut turns=0;let mut completed=None;let mut foreign=NativeInitializer{source:None,target_present:false,phase:0,written:0,target_pointer:0};let((refused,receipt),heap)=observed(||turn(grant,|cx|owner.advance(&mut foreign,&mut params,cx).is_err()));assert!(refused);assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));assert_eq!(initializer.source.as_ref().unwrap().as_ptr(),source_pointer);
  while turns<cut&&completed.is_none(){for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let((output,receipt),heap)=observed(||turn(denied,|cx|owner.advance(&mut initializer,&mut params,cx).unwrap()));assert!(output.0.is_none());assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));}let((output,receipt),heap)=observed(||turn(grant,|cx|owner.advance(&mut initializer,&mut params,cx).unwrap()));assert_eq!(output.1,receipt);assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),heap);born+=heap.0;released+=heap.1;copied+=receipt.copied_bytes;if let Some(source)=initializer.source.as_ref(){assert_eq!(source.as_ptr(),source_pointer);}completed=output.0;turns+=1;assert!(turns<16);}
  if let Some(mut session)=completed{assert!(owner.terminal_is_empty());assert!(params.is_none());let authority=unsafe{(&*session.inner.authority.get()).as_ref().unwrap()};assert_eq!(authority.job.original().unwrap().0.as_ptr()as usize,initializer.target_pointer);assert_eq!(authority.job.original().unwrap().0,[71;8192]);assert_eq!(copied,8218);session.begin_close();let mut close_turns=0;while !session.terminal_is_empty(){let(step,heap)=observed(||session.close_step(metadata));assert!(step.progress().fits(metadata));assert_eq!(step.progress().copied_bytes,0);assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;close_turns+=1;assert!(close_turns<64);}let((),heap)=observed(||drop(session));assert_eq!(heap,(0,0));}
  else{owner.begin_close();let mut close_turns=0;while !owner.terminal_is_empty(){let demand=owner.close_demands(&initializer,0).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..metadata},RetainedCloneGrant{maximum_depth:0,..metadata}]{let(step,heap)=observed(||owner.close_step(&mut initializer,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}assert_eq!(demand.copy_bytes,0);let(step,heap)=observed(||owner.close_step(&mut initializer,metadata).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);assert_eq!(step.progress().copied_bytes,0);released+=heap.1;close_turns+=1;assert!(close_turns<64);}assert!(params.is_some());let mut cancellation=semio_framework_async::CancelTokenRetirement::from_token(params.take().unwrap().cancel);while !cancellation.terminal_is_empty(){let(step,heap)=observed(||cancellation.close_step(metadata).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;}}
  assert_eq!(born,released);assert_eq!(JOB_DROPS.load(Ordering::Relaxed)-before_drops,usize::from(cut>=7));let((),heap)=observed(||{drop(owner);drop(initializer);drop(params);});assert_eq!(heap,(0,0));println!("[DEBUG] original native preparation cut={cut} turns={turns} actualCopied={copied} originalSourcePointer sameFinalNativePage physicalBornReleased={born} partialJDrop0 metadata0 terminalDrop0");
 }
}
